        let mut input = monthly_input(
            id,
            &case.base_salary,
            &case.fixed_allowances,
            case.working_days,
            case.absence_days,
            0,
            case.service_months,
        );
        input.other_deductions = Money::parse(&case.other_deductions).unwrap();
        input.loan_deduction = Money::parse(&case.loan_deduction).unwrap();
